COLLATE = utf8mb4_unicode_ci;

USE `trimix_sorveteria` ;

-- -----------------------------------------------------
-- procedure sp_abrir_caixa
-- -----------------------------------------------------

USE `trimix_sorveteria`;
DROP procedure IF EXISTS `trimix_sorveteria`.`sp_abrir_caixa`;

DELIMITER $$
USE `trimix_sorveteria`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_abrir_caixa`(IN p_id_loja INT, IN p_id_funcionario INT, IN p_valor_abertura DECIMAL(10,2))
BEGIN
  DECLARE EXIT HANDLER FOR 1062
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RN05: ja existe caixa ABERTO para esta loja.';
  INSERT INTO caixa (id_loja, id_funcionario, situacao, valor_abertura)
  VALUES (p_id_loja, p_id_funcionario, 'ABERTO', p_valor_abertura);
  SELECT LAST_INSERT_ID() AS id_caixa;
END$$

DELIMITER ;

-- -----------------------------------------------------
-- procedure sp_anonimizar_funcionario
-- -----------------------------------------------------

USE `trimix_sorveteria`;
DROP procedure IF EXISTS `trimix_sorveteria`.`sp_anonimizar_funcionario`;

DELIMITER $$
USE `trimix_sorveteria`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_anonimizar_funcionario`(IN p_id_funcionario INT, IN p_id_administrador INT)
BEGIN
  DECLARE v_perfil VARCHAR(20) DEFAULT NULL;
  DECLARE v_ativo TINYINT DEFAULT NULL;
  DECLARE v_nome VARCHAR(100) DEFAULT NULL;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;

  SELECT perfil, ativo INTO v_perfil, v_ativo
    FROM funcionario WHERE id_funcionario = p_id_administrador;
  IF v_perfil IS NULL OR v_perfil <> 'ADMINISTRADOR' OR v_ativo <> 1 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PR02: somente ADMINISTRADOR ativo pode anonimizar.';
  END IF;

  SELECT nome_funcionario INTO v_nome FROM funcionario WHERE id_funcionario = p_id_funcionario;
  IF v_nome IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PR02: funcionario inexistente.';
  END IF;
  IF v_nome = 'ANONIMIZADO_LGPD' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PR02: funcionario ja anonimizado.';
  END IF;

  START TRANSACTION;
  UPDATE funcionario
     SET nome_funcionario = 'ANONIMIZADO_LGPD',
         cpf        = LPAD(id_funcionario, 11, '0'),
         email      = CONCAT('anon_', id_funcionario, '@lgpd.local'),
         login      = CONCAT('anon_', id_funcionario),
         senha_hash = 'DESATIVADO',
         ativo      = 0
   WHERE id_funcionario = p_id_funcionario;

  INSERT INTO log_auditoria (id_funcionario, tabela_afetada, operacao, id_registro_afetado, dados_novos)
  VALUES (p_id_administrador, 'funcionario', 'ANONIMIZACAO', p_id_funcionario,
          JSON_OBJECT('nome_funcionario', 'ANONIMIZADO_LGPD', 'ativo', 0));
  COMMIT;
END$$

DELIMITER ;

-- -----------------------------------------------------
-- procedure sp_exige_funcionario_ativo
-- -----------------------------------------------------

USE `trimix_sorveteria`;
DROP procedure IF EXISTS `trimix_sorveteria`.`sp_exige_funcionario_ativo`;

DELIMITER $$
USE `trimix_sorveteria`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_exige_funcionario_ativo`(IN p_id_funcionario INT)
BEGIN
  DECLARE v_ativo TINYINT DEFAULT NULL;
  SELECT ativo INTO v_ativo FROM funcionario WHERE id_funcionario = p_id_funcionario;
  IF v_ativo IS NULL OR v_ativo = 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RN09: funcionario inexistente ou inativo.';
  END IF;
END$$

DELIMITER ;

-- -----------------------------------------------------
-- procedure sp_fechar_caixa
-- -----------------------------------------------------

USE `trimix_sorveteria`;
DROP procedure IF EXISTS `trimix_sorveteria`.`sp_fechar_caixa`;

DELIMITER $$
USE `trimix_sorveteria`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_fechar_caixa`(IN p_id_caixa INT, IN p_id_funcionario INT, IN p_valor_fechamento DECIMAL(10,2))
BEGIN
  DECLARE v_situacao VARCHAR(10) DEFAULT NULL;
  DECLARE v_abertura DECIMAL(10,2);
  DECLARE v_total_vendas DECIMAL(10,2);
  DECLARE v_esperado DECIMAL(10,2);
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;

  IF p_valor_fechamento IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RN05: valor de fechamento e obrigatorio.';
  END IF;
  CALL sp_exige_funcionario_ativo(p_id_funcionario);

  SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
  START TRANSACTION;

  SELECT situacao, valor_abertura INTO v_situacao, v_abertura
    FROM caixa WHERE id_caixa = p_id_caixa FOR UPDATE;
  IF v_situacao IS NULL OR v_situacao <> 'ABERTO' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RN05: caixa inexistente ou ja fechado.';
  END IF;

  SELECT COALESCE(SUM(iv.quantidade * (iv.preco_praticado - iv.desconto_unitario)), 0)
    INTO v_total_vendas
    FROM venda v
    JOIN item_venda iv ON iv.id_venda = v.id_venda
    LEFT JOIN estorno_venda ev ON ev.id_venda = v.id_venda
   WHERE v.id_caixa = p_id_caixa AND ev.id_venda IS NULL;

  SET v_esperado = v_abertura + v_total_vendas;

  UPDATE caixa
     SET situacao = 'FECHADO',
         id_funcionario = p_id_funcionario,
         data_fechamento = NOW(),
         valor_fechamento = p_valor_fechamento,
         valor_esperado = v_esperado,
         quebra_caixa = p_valor_fechamento - v_esperado
   WHERE id_caixa = p_id_caixa;

  COMMIT;
  SELECT p_id_caixa AS id_caixa, v_esperado AS valor_esperado,
         p_valor_fechamento AS valor_informado, (p_valor_fechamento - v_esperado) AS quebra_caixa;
END$$

DELIMITER ;

-- -----------------------------------------------------
-- procedure sp_total_vendido
-- -----------------------------------------------------

USE `trimix_sorveteria`;
DROP procedure IF EXISTS `trimix_sorveteria`.`sp_total_vendido`;

DELIMITER $$
USE `trimix_sorveteria`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_total_vendido`(IN p_data_ini DATE, IN p_data_fim DATE,
                                  IN p_id_loja INT, IN p_id_produto INT)
BEGIN
  SELECT l.id_loja, l.nome_loja, p.id_produto, p.nome_produto,
         SUM(iv.quantidade) AS quantidade_vendida,
         SUM(iv.quantidade * (iv.preco_praticado - iv.desconto_unitario)) AS total_vendido
    FROM venda v
    JOIN item_venda iv   ON iv.id_venda = v.id_venda
    JOIN produto_loja pl ON pl.id_produto_loja = iv.id_produto_loja
    JOIN produto p       ON p.id_produto = pl.id_produto
    JOIN loja l          ON l.id_loja = v.id_loja
    LEFT JOIN estorno_venda ev ON ev.id_venda = v.id_venda
   WHERE ev.id_venda IS NULL
     AND v.data_hora >= p_data_ini
     AND v.data_hora <  DATE_ADD(p_data_fim, INTERVAL 1 DAY)
     AND (p_id_loja IS NULL OR v.id_loja = p_id_loja)
     AND (p_id_produto IS NULL OR p.id_produto = p_id_produto)
   GROUP BY l.id_loja, l.nome_loja, p.id_produto, p.nome_produto
   ORDER BY l.nome_loja, total_vendido DESC;
END$$

DELIMITER ;

-- -----------------------------------------------------
-- procedure sp_transferir_estoque
-- -----------------------------------------------------

USE `trimix_sorveteria`;
DROP procedure IF EXISTS `trimix_sorveteria`.`sp_transferir_estoque`;

DELIMITER $$
USE `trimix_sorveteria`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_transferir_estoque`(
  IN p_loja_origem INT, IN p_loja_destino INT, IN p_id_funcionario INT, IN p_itens JSON)
BEGIN
  DECLARE v_done TINYINT DEFAULT 0;
  DECLARE v_id_transf INT;
  DECLARE v_id_produto INT;
  DECLARE v_qtd INT;
  DECLARE v_pl_origem INT;
  DECLARE v_pl_destino INT;
  DECLARE v_estoque INT;

  DECLARE cur_itens CURSOR FOR
    SELECT jt.id_produto, jt.quantidade
      FROM JSON_TABLE(p_itens, '$[*]' COLUMNS (
             id_produto INT PATH '$.id_produto',
             quantidade INT PATH '$.quantidade')) AS jt;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done = 1;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;

  IF p_itens IS NULL OR JSON_LENGTH(p_itens) = 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RN04: informe ao menos um item.';
  END IF;
  IF p_loja_origem = p_loja_destino THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RN04: loja de origem e destino devem ser diferentes.';
  END IF;

  SET TRANSACTION ISOLATION LEVEL SERIALIZABLE;
  START TRANSACTION;

  INSERT INTO transferencia_estoque (id_loja_origem, id_loja_destino, id_funcionario)
  VALUES (p_loja_origem, p_loja_destino, p_id_funcionario);
  SET v_id_transf = LAST_INSERT_ID();

  OPEN cur_itens;
  loop_itens: LOOP
    FETCH cur_itens INTO v_id_produto, v_qtd;
    IF v_done = 1 THEN LEAVE loop_itens; END IF;

    SET v_pl_origem = NULL; SET v_pl_destino = NULL; SET v_estoque = NULL;

    SELECT id_produto_loja, estoque_atual_caixas INTO v_pl_origem, v_estoque
      FROM produto_loja WHERE id_produto = v_id_produto AND id_loja = p_loja_origem FOR UPDATE;
    IF v_pl_origem IS NULL THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RN04: produto nao existe no catalogo da loja de origem.';
    END IF;
    IF v_estoque < v_qtd THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RN04: estoque insuficiente na loja de origem.';
    END IF;

    SELECT id_produto_loja INTO v_pl_destino
      FROM produto_loja WHERE id_produto = v_id_produto AND id_loja = p_loja_destino FOR UPDATE;
    IF v_pl_destino IS NULL THEN
      SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RN04: produto nao existe no catalogo da loja de destino.';
    END IF;

    UPDATE produto_loja SET estoque_atual_caixas = estoque_atual_caixas - v_qtd WHERE id_produto_loja = v_pl_origem;
    UPDATE produto_loja SET estoque_atual_caixas = estoque_atual_caixas + v_qtd WHERE id_produto_loja = v_pl_destino;

    INSERT INTO item_transferencia (id_transferencia_estoque, id_produto, quantidade_caixas)
    VALUES (v_id_transf, v_id_produto, v_qtd);
  END LOOP;
  CLOSE cur_itens;

  COMMIT;
  SELECT v_id_transf AS id_transferencia_estoque;
END$$

DELIMITER ;
USE `trimix_sorveteria`;

DELIMITER $$

USE `trimix_sorveteria`$$
DROP TRIGGER IF EXISTS `trimix_sorveteria`.`trg_baixa_ai` $$
USE `trimix_sorveteria`$$
CREATE
DEFINER=`root`@`localhost`
TRIGGER `trimix_sorveteria`.`trg_baixa_ai`
AFTER INSERT ON `trimix_sorveteria`.`baixa_estoque`
FOR EACH ROW
UPDATE produto_loja
     SET estoque_atual_caixas = estoque_atual_caixas - NEW.quantidade_caixas
   WHERE id_produto_loja = NEW.id_produto_loja$$


USE `trimix_sorveteria`$$
DROP TRIGGER IF EXISTS `trimix_sorveteria`.`trg_baixa_ai_log` $$
USE `trimix_sorveteria`$$
CREATE
DEFINER=`root`@`localhost`
TRIGGER `trimix_sorveteria`.`trg_baixa_ai_log`
AFTER INSERT ON `trimix_sorveteria`.`baixa_estoque`
FOR EACH ROW
INSERT INTO log_auditoria (id_funcionario, tabela_afetada, operacao, id_registro_afetado, dados_novos)
  VALUES (NEW.id_funcionario, 'baixa_estoque', 'INSERCAO', NEW.id_baixa_estoque,
          JSON_OBJECT('id_produto_loja', NEW.id_produto_loja, 'quantidade_caixas', NEW.quantidade_caixas))$$


USE `trimix_sorveteria`$$
DROP TRIGGER IF EXISTS `trimix_sorveteria`.`trg_baixa_bi` $$
USE `trimix_sorveteria`$$
CREATE
DEFINER=`root`@`localhost`
TRIGGER `trimix_sorveteria`.`trg_baixa_bi`
BEFORE INSERT ON `trimix_sorveteria`.`baixa_estoque`
FOR EACH ROW
CALL sp_exige_funcionario_ativo(NEW.id_funcionario)$$


USE `trimix_sorveteria`$$
DROP TRIGGER IF EXISTS `trimix_sorveteria`.`trg_caixa_ai` $$
USE `trimix_sorveteria`$$
CREATE
DEFINER=`root`@`localhost`
TRIGGER `trimix_sorveteria`.`trg_caixa_ai`
AFTER INSERT ON `trimix_sorveteria`.`caixa`
FOR EACH ROW
INSERT INTO log_auditoria (id_funcionario, tabela_afetada, operacao, id_registro_afetado, dados_novos)
  VALUES (NEW.id_funcionario, 'caixa', 'INSERCAO', NEW.id_caixa,
          JSON_OBJECT('id_loja', NEW.id_loja, 'situacao', NEW.situacao, 'valor_abertura', NEW.valor_abertura))$$


USE `trimix_sorveteria`$$
DROP TRIGGER IF EXISTS `trimix_sorveteria`.`trg_caixa_au` $$
USE `trimix_sorveteria`$$
CREATE
DEFINER=`root`@`localhost`
TRIGGER `trimix_sorveteria`.`trg_caixa_au`
AFTER UPDATE ON `trimix_sorveteria`.`caixa`
FOR EACH ROW
INSERT INTO log_auditoria (id_funcionario, tabela_afetada, operacao, id_registro_afetado, dados_anteriores, dados_novos)
  VALUES (NEW.id_funcionario, 'caixa', 'ALTERACAO', NEW.id_caixa,
          JSON_OBJECT('situacao', OLD.situacao),
          JSON_OBJECT('situacao', NEW.situacao, 'valor_fechamento', NEW.valor_fechamento,
                      'valor_esperado', NEW.valor_esperado, 'quebra_caixa', NEW.quebra_caixa))$$


USE `trimix_sorveteria`$$
DROP TRIGGER IF EXISTS `trimix_sorveteria`.`trg_caixa_bd` $$
USE `trimix_sorveteria`$$
CREATE
DEFINER=`root`@`localhost`
TRIGGER `trimix_sorveteria`.`trg_caixa_bd`
BEFORE DELETE ON `trimix_sorveteria`.`caixa`
FOR EACH ROW
SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PR01: caixa nao pode ser excluido.'$$


USE `trimix_sorveteria`$$
DROP TRIGGER IF EXISTS `trimix_sorveteria`.`trg_caixa_bi` $$
USE `trimix_sorveteria`$$
CREATE
DEFINER=`root`@`localhost`
TRIGGER `trimix_sorveteria`.`trg_caixa_bi`
BEFORE INSERT ON `trimix_sorveteria`.`caixa`
FOR EACH ROW
BEGIN
  CALL sp_exige_funcionario_ativo(NEW.id_funcionario);
  IF NEW.situacao <> 'ABERTO' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RN05: todo caixa nasce com situacao ABERTO.';
  END IF;
END$$


USE `trimix_sorveteria`$$
DROP TRIGGER IF EXISTS `trimix_sorveteria`.`trg_caixa_bu` $$
USE `trimix_sorveteria`$$
CREATE
DEFINER=`root`@`localhost`
TRIGGER `trimix_sorveteria`.`trg_caixa_bu`
BEFORE UPDATE ON `trimix_sorveteria`.`caixa`
FOR EACH ROW
BEGIN
  IF OLD.situacao = 'FECHADO' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'PR01: caixa FECHADO nao pode ser alterado.';
  END IF;
END$$


USE `trimix_sorveteria`$$
DROP TRIGGER IF EXISTS `trimix_sorveteria`.`trg_estorno_baixa_ai` $$
USE `trimix_sorveteria`$$
CREATE
DEFINER=`root`@`localhost`
TRIGGER `trimix_sorveteria`.`trg_estorno_baixa_ai`
AFTER INSERT ON `trimix_sorveteria`.`estorno_baixa`
FOR EACH ROW
UPDATE produto_loja pl
    JOIN baixa_estoque b ON b.id_produto_loja = pl.id_produto_loja
     SET pl.estoque_atual_caixas = pl.estoque_atual_caixas + NEW.quantidade_caixas
   WHERE b.id_baixa_estoque = NEW.id_baixa_estoque$$


USE `trimix_sorveteria`$$
DROP TRIGGER IF EXISTS `trimix_sorveteria`.`trg_estorno_baixa_ai_log` $$
USE `trimix_sorveteria`$$
CREATE
DEFINER=`root`@`localhost`
TRIGGER `trimix_sorveteria`.`trg_estorno_baixa_ai_log`
AFTER INSERT ON `trimix_sorveteria`.`estorno_baixa`
FOR EACH ROW
INSERT INTO log_auditoria (id_funcionario, tabela_afetada, operacao, id_registro_afetado, dados_novos)
  VALUES (NEW.id_funcionario, 'estorno_baixa', 'INSERCAO', NEW.id_estorno_baixa,
          JSON_OBJECT('id_baixa_estoque', NEW.id_baixa_estoque, 'quantidade_caixas', NEW.quantidade_caixas))$$


USE `trimix_sorveteria`$$
DROP TRIGGER IF EXISTS `trimix_sorveteria`.`trg_estorno_baixa_bi` $$
USE `trimix_sorveteria`$$
CREATE
DEFINER=`root`@`localhost`
TRIGGER `trimix_sorveteria`.`trg_estorno_baixa_bi`
BEFORE INSERT ON `trimix_sorveteria`.`estorno_baixa`
FOR EACH ROW
BEGIN
  DECLARE v_original INT DEFAULT NULL;
  DECLARE v_ja_estornado INT DEFAULT 0;
  CALL sp_exige_funcionario_ativo(NEW.id_funcionario);
  SELECT quantidade_caixas INTO v_original
    FROM baixa_estoque WHERE id_baixa_estoque = NEW.id_baixa_estoque;
  SELECT COALESCE(SUM(quantidade_caixas), 0) INTO v_ja_estornado
    FROM estorno_baixa WHERE id_baixa_estoque = NEW.id_baixa_estoque;
  IF v_original IS NULL OR v_ja_estornado + NEW.quantidade_caixas > v_original THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RN06: estorno excede a quantidade da baixa original.';
  END IF;
END$$


USE `trimix_sorveteria`$$
DROP TRIGGER IF EXISTS `trimix_sorveteria`.`trg_venda_ai` $$
USE `trimix_sorveteria`$$
CREATE
DEFINER=`root`@`localhost`
TRIGGER `trimix_sorveteria`.`trg_venda_ai`
AFTER INSERT ON `trimix_sorveteria`.`venda`
FOR EACH ROW
INSERT INTO log_auditoria (id_funcionario, tabela_afetada, operacao, id_registro_afetado, dados_novos)
  VALUES (NEW.id_funcionario, 'venda', 'INSERCAO', NEW.id_venda,
          JSON_OBJECT('id_loja', NEW.id_loja, 'id_caixa', NEW.id_caixa, 'data_hora', NEW.data_hora))$$


USE `trimix_sorveteria`$$
DROP TRIGGER IF EXISTS `trimix_sorveteria`.`trg_venda_bd` $$
USE `trimix_sorveteria`$$
CREATE
DEFINER=`root`@`localhost`
TRIGGER `trimix_sorveteria`.`trg_venda_bd`
BEFORE DELETE ON `trimix_sorveteria`.`venda`
FOR EACH ROW
SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RN10/PR01: venda nao pode ser excluida.'$$


USE `trimix_sorveteria`$$
DROP TRIGGER IF EXISTS `trimix_sorveteria`.`trg_venda_bi` $$
USE `trimix_sorveteria`$$
CREATE
DEFINER=`root`@`localhost`
TRIGGER `trimix_sorveteria`.`trg_venda_bi`
BEFORE INSERT ON `trimix_sorveteria`.`venda`
FOR EACH ROW
BEGIN
  DECLARE v_situacao VARCHAR(10) DEFAULT NULL;
  DECLARE v_loja_caixa INT DEFAULT NULL;
  CALL sp_exige_funcionario_ativo(NEW.id_funcionario);
  SELECT situacao, id_loja INTO v_situacao, v_loja_caixa
    FROM caixa WHERE id_caixa = NEW.id_caixa;
  IF v_situacao IS NULL OR v_situacao <> 'ABERTO' THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RN01: o caixa da venda precisa estar ABERTO.';
  END IF;
  IF v_loja_caixa <> NEW.id_loja THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RN01: o caixa pertence a outra loja.';
  END IF;
END$$


USE `trimix_sorveteria`$$
DROP TRIGGER IF EXISTS `trimix_sorveteria`.`trg_venda_bu` $$
USE `trimix_sorveteria`$$
CREATE
DEFINER=`root`@`localhost`
TRIGGER `trimix_sorveteria`.`trg_venda_bu`
BEFORE UPDATE ON `trimix_sorveteria`.`venda`
FOR EACH ROW
SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'RN10: venda e imutavel. Use estorno (RN11).'$$


USE `trimix_sorveteria`$$
DROP TRIGGER IF EXISTS `trimix_sorveteria`.`trg_estorno_venda_ai` $$
USE `trimix_sorveteria`$$
